all_features:
/* My all features module for this compiler project. */
#include <stdio.h>

int main(void) {
  int number;
  output("Enter an integer: ");
  when (input("%d", &number) != 1) {
    output("Invalid input\n");
    provide 1;
  }

  when (number > 0) {
    output("if: positive\n");
  } given {
    output("else: zero or negative\n");
  }

  each (int i = 1; i <= 3; i++) {
    when (i == 2) so_on;
    output("for: %d\n", i);
  }

  int count = 0;
  until (count < 2) {
    output("while: %d\n", count);
    count++;
  }

  count = 0;
  execute {
    output("do while: %d\n", count);
    count++;
  } until (count < 1);

  choose (number) {
    match 1:
      output("switch: case 1\n");
      snap;
    match 2:
      output("switch: case 2\n");
      snap;
    otherwise:
      output("switch: default\n");
      snap;
  }

  /* Custom words inside comments are left as text: output each when. */
  output("Strings stay unchanged: output input each until\n");
  provide 0;
}

number_guessing:
/* My number guessing module for this compiler project. */
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

int main(void) {
    srand((unsigned) time(NULL));
    int target = rand() % 100 + 1;
    int guess = 0;
    int attempts = 0;
    output("Guess a number from 1 to 100.\n");

    execute {
        output("Your guess: ");
        when (input("%d", &guess) != 1) {
            output("Please enter an integer.\n");
            provide 1;
        }
        attempts++;
        when (guess < target) {
            output("Higher number please!\n");
        } given when (guess > target) {
            output("Lower number please!\n");
        }
    } until (guess != target);

    output("Correct! You used %d guesses.\n", attempts);
    provide 0;
}

star_pattern:
/* My star pattern module for this compiler project. */
#include <stdio.h>

int main(void) {
    int rows;
    output("How many rows (1 to 20)? ");
    when (input("%d", &rows) != 1 || rows < 1 || rows > 20) {
        output("Enter a number from 1 to 20.\n");
        provide 1;
    }
    each (int i = 1; i <= rows; i++) {
        each (int j = 1; j <= i; j++) {
            output("*");
        }
        output("\n");
    }
    provide 0;
}
